 for(const data of [{...savedPublishReceipt,flowId:U},{...savedPublishReceipt,draftRevision:2},{...savedPublishReceipt,extra:true},{...savedPublishReceipt,publication:{...publicationReceipt,hostedPath:'/foreign'}},{...savedPublishReceipt,publication:{...publicationReceipt,extra:true}}]){const f=transport([json({access_token:'private-owner'}),json({id:U}),json({ok:true,data:ownerDraft}),json({ok:true,data})]);const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');await c.loadPaidSimpleDraft(T,F);await expect(c.publishPaidSimpleDraft(T,F,savedPublishInput)).rejects.toMatchObject({delivery:'unknown'});expect(c.paidSimpleSavedDraftPublicationState(T).phase).toBe('unknown');}
 const f=transport([json({access_token:'private-owner'}),json({id:U}),json({ok:true,data:ownerDraft}),json({ok:false,code:'INTERNAL_ERROR'},500)]);const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');await c.loadPaidSimpleDraft(T,F);await expect(c.publishPaidSimple(T,U,publicationInput)).rejects.toMatchObject({delivery:'unknown'});await expect(c.publishPaidSimpleDraft(T,F,savedPublishInput)).rejects.toMatchObject({delivery:'not_sent'});expect(f).toHaveBeenCalledTimes(4);
