it('requires fresh loaded fields after a definitive first conflict and discards late receipts after session changes',async()=>{
 let resolve!:(response:Response)=>void;let n=0;const f=vi.fn<typeof fetch>(async()=>++n===1?json({access_token:'private-owner'}):n===2?json({id:U}):n===3?json({ok:true,data:ownerDraft}):n===4?json({ok:false,code:'CONFLICT'},409):n===5?json({ok:true,data:{...ownerDraft,revision:2}}):new Promise(r=>resolve=r));const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');await c.loadPaidSimpleDraft(T,F);await expect(c.publishPaidSimpleDraft(T,F,savedPublishInput)).rejects.toMatchObject({delivery:'rejected'});await expect(c.publishPaidSimpleDraft(T,F,savedPublishInput)).rejects.toMatchObject({delivery:'not_sent'});await c.loadPaidSimpleDraft(T,F);const pending=c.publishPaidSimpleDraft(T,F,{...savedPublishInput,expectedDraftRevision:2});c.signOut();resolve(json({ok:true,data:{...savedPublishReceipt,draftRevision:2}}));await expect(pending).rejects.toThrow('session changed');expect(c.paidSimpleSavedDraftPublicationState(T)).toEqual({phase:'ready'});expect(c.paidSimplePublicationState(T)).toEqual({phase:'ready'});
});

it('verifies accepted HTTP saved-draft publication and same revision replay with exact authoritative nested receipts',async()=>{
 const origin='https://portal.example.test',ownerToken='synthetic-http-owner-token';let published:{flowId:string;draftRevision:number;versionId:string;installationId:string;renderSchemaVersion:3;replayed:boolean}|undefined,loseReceipt=true,writes=0;
 const rpc=vi.fn(async(name:string,args:readonly unknown[])=>{if(args[0]!==U||args[1]!==T||args[2]!==F)throw new FlowError('FORBIDDEN');if(name==='get_paid_simple_draft')return ownerDraft;if(name!=='publish_paid_simple_draft')throw Error('Unexpected writer');if(args[3]!==1)throw new FlowError('CONFLICT');if(!published){writes++;published={flowId:F,draftRevision:1,versionId:String(args[4]),installationId:String(args[5]),renderSchemaVersion:3,replayed:false};}else published={...published,replayed:true};return published;});
 const server=createFlowHttpServer({repository:{call:rpc},ownerOrigins:[origin],customerOrigins:[publicationInput.checkoutOrigin],authenticateOwner:async token=>token===ownerToken?U:null,paidSimplePublication:true,paidPublication:async()=>null});await new Promise<void>(r=>server.listen(0,'127.0.0.1',r));
 try{const address=server.address() as {port:number};const f=vi.fn<typeof fetch>(async(input,options)=>{const url=new URL(String(input));if(url.pathname==='/auth/v1/token')return json({access_token:ownerToken});if(url.pathname==='/auth/v1/user')return json({id:U});const response=await fetch('http://127.0.0.1:'+address.port+url.pathname+url.search,{...options,headers:{...options?.headers,Origin:origin}});if(url.pathname.endsWith('/publish-draft')&&response.ok&&loseReceipt){loseReceipt=false;await response.text();throw Error('Lost real HTTP receipt');}return response;});const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');await c.loadPaidSimpleDraft(T,F);await expect(c.publishPaidSimpleDraft(T,F,savedPublishInput)).rejects.toMatchObject({delivery:'unknown'});const receipt=await c.publishPaidSimpleDraft(T,F,savedPublishInput);expect(receipt).toEqual({flowId:F,draftRevision:1,publication:{versionId:published!.versionId,installationId:published!.installationId,renderSchemaVersion:3,hostedPath:'/checkout/flow/'+published!.installationId}});expect(writes).toBe(1);expect(published!.replayed).toBe(true);expect(Object.keys(receipt)).toEqual(['flowId','draftRevision','publication']);expect(f.mock.calls[3]?.[1]?.body).toBe(f.mock.calls[4]?.[1]?.body);expect(rpc.mock.calls.filter(([name])=>name==='publish_paid_simple_draft').every(([,args])=>args[0]===U&&args[1]===T&&args[2]===F&&args[3]===1&&JSON.stringify(args[6])===JSON.stringify([publicationInput.checkoutOrigin]))).toBe(true);await expect(c.publishPaidSimpleDraft(S,F,savedPublishInput)).rejects.toMatchObject({delivery:'not_sent'});
 }finally{server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(e=>e?reject(e):resolve()));}
},15000);
